def fraction_from_continued(terms):
    num, den = terms[-1], 1
    for a in reversed(terms[:-1]):
        num, den = a * num + den, num
    if den < 0:
        num, den = -num, -den
    g = gcd(num, den)
    if g == 0:
        g = 1
    return (num // g, den // g)

def is_narcissistic_in_base(n, b):
    x = n
    digits = []
    if x == 0:
        digits = [0]
    else:
        while x > 0:
            digits.append(x % b)
            x //= b
    k = len(digits)
    return n == sum(d ** k for d in digits)

