def sum_common_divisors(a, b):
    g = gcd(a, b)
    total = 0
    i = 1
    while i * i <= g:
        if g % i == 0:
            total += i
            j = g // i
            if j != i:
                total += j
        i += 1
    return total

def convert_base_to_base(s, from_base, to_base):
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    value = 0
    for ch in s.lower():
        value = value * from_base + digits.index(ch)
    if value == 0:
        return "0"
    result = []
    while value > 0:
        result.append(digits[value % to_base])
        value //= to_base
    return ''.join(reversed(result))

