def count_semiprimes_in_range(a, b):
    def is_semiprime(n):
        if n < 4:
            return False
        count = 0
        x = n
        d = 2
        while d * d <= x:
            while x % d == 0:
                x //= d
                count += 1
                if count > 2:
                    return False
            d += 1
        if x > 1:
            count += 1
        return count == 2

    total = 0
    for x in range(a, b + 1):
        if is_semiprime(x):
            total += 1
    return total

def sort_leaderboard(entries):
    sorted_entries = sorted(entries, key=lambda e: (-e[1], e[0]))
    return [e[0] for e in sorted_entries]

def sort_products_by_price_then_rating(products):
